// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        // current owner is address(0) after deployment; ensure caller is NOT the owner
        vm.assume(actor != c.owner());

        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        // General rule: a non-owner caller can never transfer ownership.
        assertTrue(!ok, "non-owner must not be able to transferOwnership");
    }
}
